from rules import resolve


def solve(data):
    return resolve(data)

def _interval(value):
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return value[0], value[1]
    if isinstance(value, dict):
        lo = value.get('min', value.get('minimum', value.get('min_version')))
        hi = value.get('max', value.get('maximum', value.get('max_version')))
        return lo, hi
    if value is None:
        return None, None
    return value, value


def _dependency(dep):
    if isinstance(dep, str):
        return dep, (None, None)
    if isinstance(dep, dict):
        name = next((dep[k] for k in ('name', 'package', 'pkg', 'id') if k in dep), None)
        if name is None and len(dep) == 1:
            name, value = next(iter(dep.items()))
            return name, _interval(value)
        if name is None:
            return None, (None, None)
        value = next((dep[k] for k in ('range', 'versions', 'bounds', 'constraint') if k in dep), None)
        if value is None and 'version' in dep:
            value = dep['version']
        if value is not None:
            return name, _interval(value)
        return name, (dep.get('min', dep.get('minimum', dep.get('min_version'))),
                      dep.get('max', dep.get('maximum', dep.get('max_version'))))
    if isinstance(dep, (list, tuple)) and dep:
        name = dep[0]
        if len(dep) == 1:
            return name, (None, None)
        if len(dep) >= 3:
            return name, (dep[1], dep[2])
        return name, _interval(dep[1])
    return None, (None, None)


def _within(version, bounds):
    lo, hi = bounds
    return (lo is None or version >= lo) and (hi is None or version <= hi)


def _intersect(first, second):
    lo1, hi1 = first
    lo2, hi2 = second
    lo = lo1 if lo2 is None else lo2 if lo1 is None else max(lo1, lo2)
    hi = hi1 if hi2 is None else hi2 if hi1 is None else min(hi1, hi2)
    return lo, hi


def _acyclic(selected, features):
    graph = {}
    for name, row in selected.items():
        edges = []
        for dep in row.get('deps', []):
            if isinstance(dep, dict):
                feature = dep.get('feature')
                if feature is not None and feature != '' and feature not in features:
                    continue
            dep_name, _ = _dependency(dep)
            if dep_name is not None:
                edges.append(dep_name)
        graph[name] = edges

    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dependency in graph.get(name, ()):
            if not visit(dependency):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)


def resolve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    initial_bounds = {name: _interval(value) for name, value in roots.items()}
    best_score = None
    best = None

    def search(assigned, selected, required, bounds):
        nonlocal best_score, best

        for name, version in assigned.items():
            if not _within(version, bounds.get(name, (None, None))):
                return

        pending = sorted(required - set(assigned))
        if not pending:
            if not _acyclic(selected, features):
                return
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best = dict(assigned)
            return

        name = pending[0]
        forbidden = blocked.get(name, ())
        for row in packages.get(name, ()):
            version = row['version']
            if version in forbidden or not _within(version, bounds.get(name, (None, None))):
                continue
            if name in pins and version != pins[name]:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_selected = dict(selected)
            next_selected[name] = row
            next_required = set(required)
            next_bounds = dict(bounds)
            valid = True

            for dep in row.get('deps', []):
                if isinstance(dep, dict):
                    feature = dep.get('feature')
                    if feature is not None and feature != '' and feature not in features:
                        continue
                dep_name, restriction = _dependency(dep)
                if dep_name is None:
                    continue
                next_required.add(dep_name)
                next_bounds[dep_name] = _intersect(
                    next_bounds.get(dep_name, (None, None)), restriction
                )
                lo, hi = next_bounds[dep_name]
                if lo is not None and hi is not None and lo > hi:
                    valid = False
                    break

            if valid:
                search(next_assigned, next_selected, next_required, next_bounds)

    search({}, {}, set(roots), initial_bounds)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}
